/**
 * Fails if the repository tracks an art asset: `npm run check:assets`.
 *
 * Everything visual and audible in the game is generated by code, so no
 * model, texture, image, audio, video or font file may be committed. The
 * only exception is `docs/images/`, for screenshots in the documentation.
 * Generated map data are `.json` and `.bin` files, which are not assets.
 */

import { execFileSync } from 'node:child_process';

const ALLOWED_PREFIX = 'docs/images/';

const FORBIDDEN_EXTENSIONS = new Set([
  // models
  'glb', 'gltf', 'obj', 'mtl', 'fbx', 'dae', 'stl', 'ply', '3ds', 'blend', 'usd', 'usdz', 'vox',
  // textures and images
  'png', 'jpg', 'jpeg', 'webp', 'gif', 'svg', 'bmp', 'tga', 'tif', 'tiff', 'ico', 'avif', 'heic',
  'psd', 'exr', 'hdr', 'ktx', 'ktx2', 'dds', 'basis',
  // audio
  'mp3', 'ogg', 'wav', 'flac', 'aac', 'm4a', 'opus', 'mid', 'midi',
  // video
  'mp4', 'webm', 'mov', 'avi', 'mkv',
  // fonts
  'ttf', 'otf', 'woff', 'woff2', 'eot',
]);

const tracked = execFileSync('git', ['ls-files', '-z'], { encoding: 'utf8' })
  .split('\0')
  .filter((file) => file !== '');

const offending = tracked.filter((file) => {
  if (file.startsWith(ALLOWED_PREFIX)) return false;
  const name = file.slice(file.lastIndexOf('/') + 1);
  const dot = name.lastIndexOf('.');
  return dot >= 0 && FORBIDDEN_EXTENSIONS.has(name.slice(dot + 1).toLowerCase());
});

if (offending.length > 0) {
  console.error(`check:assets: ${offending.length} asset file(s) tracked outside ${ALLOWED_PREFIX}:`);
  for (const file of offending) console.error(`  ${file}`);
  process.exit(1);
}
console.log(`check:assets: ${tracked.length} tracked files, no asset files outside ${ALLOWED_PREFIX}`);
